const beforeReceptionRender=render;
function receptionRecords(){return state.repairs.filter(r=>r.receivedBy&&(currentPerson==='Dueña'||r.receivedBy===currentPerson)).sort((a,b)=>(b.receivedAt||0)-(a.receivedAt||0))}
function receptionCard(r){return `<button class="reception-record" onclick="receptionRecord('${r.id}')"><span class="reception-garment">${icon(r.kind||'shirt')}</span><span><strong>${esc(r.garment)}</strong><small>${r.id} · Cliente: ${esc(r.client)}</small><em>${esc(r.task)} · ${esc(r.date)}</em><b>Recibió ${esc(r.receivedBy)} · Responsable actual: ${esc(holder(r.id))}</b></span><i>›</i></button>`}
function receptionPage(){const owner=currentPerson==='Dueña',rows=receptionRecords(),allowed=owner||staffProfile(currentPerson).canReceive;return `${owner?'<button class="back-link" onclick="ownerNavigate(\'overview\')">← Resumen del taller</button>':''}<div class="greeting"><p class="eyebrow">${owner?'RECEPCIÓN DEL LOCAL':'TU TAREA EN EL LOCAL'}</p><h1>${owner?'Prendas de clientes':'Prendas de clientes'}</h1><p class="sub">${owner?'Consulta el encargo del cliente y quién está haciendo el arreglo.':'Cuando un cliente deje una prenda, regístrala aquí.'}</p></div>${!owner&&allowed?`<section class="reception-hero"><span class="reception-icon">${icon('location')}</span><div><span class="reception-tag">ENCARGADA DE RECEPCIÓN</span><h2>${esc(currentPerson)}, tú recibes la prenda.</h2><p>Registra lo que pidió el cliente. Después puedes hacer el arreglo o pedir apoyo a una compañera.</p></div><button onclick="receiveGarment()">${icon('plus')} Recibir prenda del cliente</button></section>`:owner?ownerReceptionInfo():'<div class="notice">La dueña debe habilitarte para registrar prendas recibidas en el local.</div>'}<div class="section-label"><h2>${owner?'Registro del local':'Lo que recibiste'}</h2><span>${rows.length} ${rows.length===1?'prenda':'prendas'}</span></div><div class="reception-records">${rows.map(receptionCard).join('')||`<div class="reception-empty">${icon('box')}<h3>Aún no hay prendas registradas</h3><p>${owner?'Los registros aparecerán cuando la encargada reciba una prenda del cliente.':'Toca “Recibir prenda del cliente” cuando alguien deje su encargo.'}</p></div>`}</div>${!owner?'<button class="flow-help" onclick="navigate(\'apoyo\')">'+icon('help')+' Necesito ayuda con la recepción</button>':''}`}
function receptionRecord(id){const r=state.repairs.find(r=>r.id===id);if(!r)return;if(currentPerson!=='Dueña'&&r.receivedBy!==currentPerson)return;modal('Registro de recepción',`<p><strong>${esc(r.garment)} · ${r.id}</strong></p><div class="notice">Cliente: ${esc(r.client)}<br>Contacto: ${esc(r.phone||'No registrado')}<br>Arreglo: ${esc(r.task)}</div><p>${esc(r.instructions)}</p><dl class="profile-facts"><div><dt>Recibió al cliente</dt><dd>${esc(r.receivedBy)} · ${esc(r.received||'')}</dd></div><div><dt>Local de recepción</dt><dd>${esc(r.branch||'Rapicostura')}</dd></div><div><dt>Responsable actual del arreglo</dt><dd>${esc(holder(r.id))}</dd></div><div><dt>Entrega acordada</dt><dd>${esc(r.date)}</dd></div><div><dt>Precio al cliente</dt><dd>${repairMoney(r.price)}</dd></div></dl>${holder(r.id)===currentPerson?button('Ver mi trabajo',`dialog.close();openRepair('${r.id}')`,true,'orders'):''}`)}
function ownerReceptionInfo(){const names=Object.values(state.staffProfiles||{}).filter(p=>p.status==='active'&&p.canReceive).map(p=>p.name);return `<section class="owner-reception-info"><span>${icon('location')}</span><div><strong>${names.length===1?'Encargada de recepción':'Trabajadoras habilitadas en el local'}</strong><p>${esc(names.join(' · ')||'Todavía no hay una encargada habilitada.')}</p><small>Es una función del equipo. No requiere otro tipo de cuenta.</small></div><button onclick="staffTab='profiles';ownerNavigate('members')">Cambiar encargada →</button></section>`}
function ownerReceptionShortcut(){return `<section class="owner-reception-shortcut"><div>${icon('location')}<span><strong>Prendas de clientes</strong><small>${Object.values(state.staffProfiles||{}).filter(p=>p.status==='active'&&p.canReceive).map(p=>esc(p.name)).join(' · ')||'Sin encargada habilitada'} · ${state.repairs.filter(r=>r.receivedBy).length} ${state.repairs.filter(r=>r.receivedBy).length===1?'prenda registrada':'prendas registradas'}</small></span></div><button onclick="ownerNavigate('reception')">Ver prendas de clientes ${icon('arrow')}</button></section>`}
render=function(){beforeReceptionRender();if(currentPerson==='Dueña'){if(page==='reception')main.innerHTML=receptionPage()+personaControl();else if(!ownerDemo&&['overview','inicio'].includes(page)){const kpis=main.querySelector('.owner-kpis');if(kpis)kpis.insertAdjacentHTML('afterend',ownerReceptionShortcut())}return}const p=staffProfile(currentPerson);if(page==='reception'){main.innerHTML=receptionPage()+personaControl()}if(p.canReceive){const nav=document.getElementById('mobile-nav');const helpButton=[...nav.querySelectorAll('button')].find(b=>b.textContent.trim()==='Ayuda');if(helpButton)helpButton.outerHTML=`<button class="${page==='reception'?'active':''}" ${page==='reception'?'aria-current="page"':''} onclick="navigate('reception')">${icon('location')}<span>Clientes</span></button>`;if(page==='inicio'&&!selectedRepair){const receive=main.querySelector('.receive-new');if(receive){receive.innerHTML=icon('location')+' Ver prendas de clientes';receive.onclick=()=>navigate('reception')}}}};
if(new URLSearchParams(location.search).get('vista')==='recepcion'){currentPerson='Rosa';page='reception'}
render();
